from pathlib import Path
import urllib.request, hashlib, json
out=Path('/home/hal/dev/interp/metis/experiments/positive-openmm/run14/agent/intake')
out.mkdir(parents=True, exist_ok=True)
brief=Path('/home/hal/dev/interp/metis/experiments/positive-openmm/BRIEF.md').read_bytes()
(out/'brief.md').write_bytes(brief)
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
for name in ['examples/benchmark.py','examples/5dfr_solv-cube_equil.pdb','wrappers/python/openmm/app/data/amber99sb.xml','wrappers/python/openmm/app/data/tip3p.xml']:
 try:
  b=urllib.request.urlopen(base+name,timeout=30).read()
  print(json.dumps(dict(path=name,bytes=len(b),sha256=hashlib.sha256(b).hexdigest())))
  if name.endswith('benchmark.py'):
   lines=b.decode().splitlines()
   for i,line in enumerate(lines):
    if any(s in line for s in ['5dfr','amber99sb','LangevinMiddle','hydrogenMass','Deterministic','add_option','constraintTolerance']):
     print(str(i+1)+': '+line)
 except Exception as e: print(json.dumps(dict(path=name,error=str(e))))
for package in ['openmm','OpenMM-CUDA-12']:
 try:
  d=json.load(urllib.request.urlopen('https://pypi.org/pypi/'+package+'/8.2.0/json',timeout=30))
  print(json.dumps(dict(package=package,requires_dist=d['info'].get('requires_dist'),license=d['info'].get('license'),linux_wheels=[{'filename':u['filename'],'sha256':u['digests']['sha256'],'bytes':u['size']} for u in d['urls'] if 'manylinux' in u['filename']])))
 except Exception as e: print(str(e))
PY"

